body.query:
query summary($q: String, $predicate: Predicate, $checklistKey: ID){
  occurrenceSearch(q: $q, predicate: $predicate) {
    documents(size: 0) {
      total
    }
    cardinality {
      speciesKey(checklistKey: $checklistKey)
    }

    stats {
      year {
        min
        max
      }
    }
  }
}
